sys_script_include.script:
var WF_ProblemAccess = Class.create();
WF_ProblemAccess.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    canEditAssignedTo: function() {
        answer = true;
        var statevalue = current.state;
        if (statevalue == '106') {
            if (gs.hasRole('x_g_wfb_inc_mgmt.wf_incprb_process_owner') || gs.getUser().isMemberOf(current.assignment_group)) {
                answer = true;
            } else {
                answer = false;
            }
        } else {
            if (!current.isNewRecord() && current.assignment_group != '') {
                if (current.major_problem == true) {
                    if (gs.hasRole('problem_manager') || gs.hasRole('x_g_wfb_inc_mgmt.wf_incprb_process_owner')) {
                        answer = true;
                    } else {
                        answer = false;
                    }
                } else {
                    //As per LGWH-26784
                    if (current.getValue("state") === "101") {
                        answer = true;
                    } else if (gs.hasRole('x_g_wfb_inc_mgmt.wf_incprb_process_owner') || gs.getUser().isMemberOf(current.assignment_group)) {
                        answer = true;
                    } else {
                        answer = false;
                    }
                }
            }
        }
        return answer;
    },

    canEditProblemRecord: function() {
        answer = true;
        if (!current.isNewRecord() && current.assignment_group != '') {
            if (current.major_problem == true) {
                if (gs.hasRole('problem_manager') || gs.hasRole('x_g_wfb_inc_mgmt.wf_incprb_process_owner')) {
                    answer = true;
                } else {
                    answer = false;
                }
            } else {
                //As per LGWH-26784
                if (current.getValue("state") === "101") {
                    answer = true;
                } else if (gs.hasRole('x_g_wfb_inc_mgmt.wf_incprb_process_owner') || gs.getUser().isMemberOf(current.assignment_group)) {
                    answer = true;
                } else {
                    answer = false;
                }
            }
        }
        return answer;
    },
    // LGWH-26314 Restrict major problem checkbox selection
    // Function to check if the user can edit major problems
    canEditMajorProblem: function(current) {
        // Declare a variable to store the answer, default to undefined
        var answer;

        // Check if the user has the "problem_manager" role and is a member of the assignment group
        if (gs.hasRole("problem_manager") && gs.getUser().isMemberOf(current.assignment_group)) {
            // Set the answer to true if the conditions are met
            answer = true;
        } else {
            // Set the answer to false if the conditions are not met
            answer = false;
        }

        // Return the final answer
        return answer;
    },

    canEditDueDate: function() {
        answer = false;
        if (current.state.getValue("state") === "103" || current.state.getValue("state") === "104") { //.changesTo('104')){ //
            if (gs.hasRole('x_g_wfb_inc_mgmt.wf_incprb_process_owner')) {
                answer = true;
            } else if (current.major_problem == true) {
                if (gs.hasRole('problem_manager')) {
                    answer = true;
                }
            } else if (gs.getUser().isMemberOf(current.assignment_group)) {
                answer = true;
            }
        }
        return answer;
    },
    // canEditDueDate: function() {
    //     answer = true;
    //     if (!gs.hasRole('x_g_wfb_inc_mgmt.wf_incprb_process_owner')) {
    //         if (current.major_problem == true) {
    //             if (!gs.hasRole('problem_manager')) {
    //                 answer = false;
    //             }
    //         } else if (!gs.getUser().isMemberOf(current.assignment_group)) {
    //             answer = false;
    //         }
    //     }
    //     return answer;
    // },


    type: 'WF_ProblemAccess'
});
